BEGIN;SET LOCAL statement_timeout='30s';
DO $$DECLARE native uuid;actor uuid;org uuid:=gen_random_uuid();other uuid:=gen_random_uuid();project uuid:=gen_random_uuid();foreign_project uuid:=gen_random_uuid();b uuid:=gen_random_uuid();f uuid:=gen_random_uuid();u uuid:=gen_random_uuid();pkg uuid:=gen_random_uuid();foreign_pkg uuid:=gen_random_uuid();inst uuid:=gen_random_uuid();template uuid;appliance uuid:=gen_random_uuid();delivery uuid:=gen_random_uuid();n int;deal uuid:=gen_random_uuid();spec uuid:=gen_random_uuid();specpkg uuid:=gen_random_uuid();contact uuid:=gen_random_uuid();foreign_contact uuid:=gen_random_uuid();company uuid:=gen_random_uuid();foreign_company uuid:=gen_random_uuid();source_product uuid:=gen_random_uuid();alt_pkg uuid:=gen_random_uuid();alt_product uuid:=gen_random_uuid();foreign_spec uuid:=gen_random_uuid();foreign_specpkg uuid:=gen_random_uuid();foreign_product uuid:=gen_random_uuid();store uuid:=gen_random_uuid();store_pkg uuid:=gen_random_uuid();r jsonb;r2 jsonb;
BEGIN
 SELECT target_user_id,source_user_id INTO native,actor FROM tj.source_user_identity_map i WHERE activation_status='activated' AND NOT EXISTS(SELECT 1 FROM tj.platform_admins a WHERE a.user_id=i.source_user_id) LIMIT 1;
 INSERT INTO tj.organizations(id,name,slug) VALUES(org,'Rollback IQBuild',org::text),(other,'Rollback foreign IQBuild',other::text);
 INSERT INTO tj.organization_members(organization_id,user_id,role,status) VALUES(org,actor,'owner','active'),(other,actor,'owner','active');
 INSERT INTO tj.platform_user_context(user_id,organization_id,source_module_key) VALUES(actor,org,'iq-build') ON CONFLICT(user_id) DO UPDATE SET organization_id=org,location_id=NULL;
 INSERT INTO tj.companies(id,organization_id,name) VALUES(company,org,'Fixture company'),(foreign_company,other,'Foreign company');
 INSERT INTO tj.contacts(id,organization_id,first_name) VALUES(contact,org,'Fixture contact'),(foreign_contact,other,'Foreign contact');
 INSERT INTO tj.org_locations(id,organization_id,location_type,name) VALUES(store,org,'store','Rollback store');
 INSERT INTO tj.org_location_members(organization_id,location_id,user_id,is_active) VALUES(org,store,actor,true);
 INSERT INTO tj.crm_deals(id,organization_id,owner_user_id,title,stage,value_amount,value_currency) VALUES(deal,org,actor,'Fixture won deal','Closed Won',1234.56,'CAD');
 INSERT INTO tj.speciq_projects(id,organization_id,customer_name,project_name,deal_id) VALUES(spec,org,'Fixture customer','Spec source',deal);
 INSERT INTO tj.speciq_packages(id,organization_id,project_id,package_name,deal_id,total_final,quote_issued_at) VALUES(specpkg,org,spec,'Source package',deal,1234.56,now()-interval '2 days');
 INSERT INTO tj.speciq_packages(id,organization_id,project_id,package_name) VALUES(alt_pkg,org,spec,'Alternate source package');
 INSERT INTO tj.speciq_package_products(id,package_id,organization_id,product_name) VALUES(alt_product,alt_pkg,org,'Alternate source appliance');
 INSERT INTO tj.speciq_projects(id,organization_id,customer_name,project_name) VALUES(foreign_spec,other,'Foreign fixture','Foreign source');
 INSERT INTO tj.speciq_packages(id,organization_id,project_id,package_name) VALUES(foreign_specpkg,other,foreign_spec,'Foreign source package');
 INSERT INTO tj.speciq_package_products(id,package_id,organization_id,product_name) VALUES(foreign_product,foreign_specpkg,other,'Foreign source appliance');
 INSERT INTO tj.speciq_package_products(id,package_id,organization_id,product_name,model_number,category,msrp,negotiated_price,width_inches,specifications,image_url,updated_at) VALUES(source_product,specpkg,org,'Source appliance','Evidence model','refrigerator',1500,0,36,'{"capacity":"Recorded capacity"}','https://example.invalid/fixture.jpg',now()-interval '2 days');
 PERFORM set_config('request.jwt.claim.sub',native::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 INSERT INTO tj.iqbuild_projects(id,organization_id,name) VALUES(project,org,'Rollback project'),(foreign_project,other,'Foreign project');
 UPDATE tj.iqbuild_projects SET crm_contact_id=contact,crm_company_id=company WHERE id=project;
 BEGIN UPDATE tj.iqbuild_projects SET crm_contact_id=foreign_contact WHERE id=project;RAISE EXCEPTION 'Foreign CRM contact accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN UPDATE tj.iqbuild_projects SET crm_company_id=foreign_company WHERE id=project;RAISE EXCEPTION 'Foreign CRM company accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN UPDATE tj.iqbuild_projects SET crm_contact_id=gen_random_uuid() WHERE id=project;RAISE EXCEPTION 'Missing CRM contact accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO tj.iqbuild_buildings(id,project_id,name) VALUES(b,project,'Building');
 INSERT INTO tj.iqbuild_floors(id,building_id,floor_number) VALUES(f,b,1);
 INSERT INTO tj.iqbuild_packages(id,project_id,name) VALUES(pkg,project,'Package'),(foreign_pkg,foreign_project,'Foreign package');
 INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,brand,model,unit_cost,notes) VALUES(pkg,'refrigerator','Recorded brand','Recorded model',1234.56,'Source quote retained');
 INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,speciq_product_id) VALUES(pkg,'refrigerator',source_product);
 BEGIN INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,speciq_product_id) VALUES(pkg,'refrigerator',foreign_product);RAISE EXCEPTION 'Foreign SpecIQ product accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,speciq_product_id) VALUES(pkg,'refrigerator',gen_random_uuid());RAISE EXCEPTION 'Missing SpecIQ product accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO tj.iqbuild_package_items(package_id,appliance_type) VALUES(pkg,'refrigerator');
 IF NOT EXISTS(SELECT 1 FROM tj.iqbuild_package_items WHERE package_id=pkg AND speciq_product_id IS NULL AND unit_cost IS NULL AND notes IS NULL) THEN RAISE EXCEPTION 'Unknown manual item price invented';END IF;
 INSERT INTO tj.iqbuild_units(id,floor_id,unit_number,package_id) VALUES(u,f,'101',pkg);
 INSERT INTO tj.iqbuild_deliveries(id,project_id,target_building_id,delivery_date) VALUES(delivery,project,b,current_date);
 INSERT INTO tj.iqbuild_unit_appliances(id,unit_id,appliance_type,brand,model,delivery_id) VALUES(appliance,u,'refrigerator','Recorded brand','Recorded model',delivery);
 INSERT INTO tj.iqbuild_milestone_templates(organization_id,name) VALUES(org,'Fixture prerequisite') RETURNING id INTO template;
 INSERT INTO tj.iqbuild_unit_milestones(unit_id,milestone_template_id) VALUES(u,template);
 INSERT INTO tj.iqbuild_project_contacts(project_id,name,role) VALUES(project,'Fixture contact','site_manager');
 INSERT INTO tj.iqbuild_team_members(project_id,name) VALUES(project,'Fixture team');
 INSERT INTO tj.iqbuild_installations(id,project_id,building_id,floor_id,unit_id) VALUES(inst,project,b,f,u);
 INSERT INTO tj.iqbuild_installation_parts(installation_id,unit_appliance_id,part_type,part_name) VALUES(inst,appliance,'installation','Fixture part');
 INSERT INTO tj.iqbuild_signoffs(project_id,entity_type,entity_id,signoff_type,signed_by) VALUES(project,'unit',u,'completion','Fixture signer');
 INSERT INTO tj.iqbuild_activity_log(project_id,entity_type,entity_id,action) VALUES(project,'unit',u,'recorded');
 r:=public.tj_runtime_iqbuild_import(deal,'{"name":"Atomic imported fixture"}');r2:=public.tj_runtime_iqbuild_import(deal,'{"name":"Retry must preserve original"}');IF r->>'project_id'<>r2->>'project_id' OR r->>'packages'<>'1' OR r->>'items'<>'1' OR r2->>'already_imported'<>'true' THEN RAISE EXCEPTION 'Atomic import/retry failed';END IF;
 BEGIN INSERT INTO tj.iqbuild_package_items(package_id,appliance_type,speciq_product_id) VALUES((SELECT id FROM tj.iqbuild_packages WHERE project_id=(r->>'project_id')::uuid LIMIT 1),'refrigerator',alt_product);RAISE EXCEPTION 'Wrong source package product accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE tj.iqbuild_package_items SET source_recorded_at=now() WHERE package_id IN(SELECT id FROM tj.iqbuild_packages WHERE project_id=(r->>'project_id')::uuid);RAISE EXCEPTION 'Source date overwrite accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN UPDATE tj.iqbuild_projects SET import_summary='{}' WHERE id=(r->>'project_id')::uuid;RAISE EXCEPTION 'Import evidence overwrite accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE tj.iqbuild_units SET notes='Saved note' WHERE id=u;
 BEGIN INSERT INTO tj.iqbuild_buildings(project_id,organization_id,name) VALUES(project,other,'Cross-org');RAISE EXCEPTION 'Spoof accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN INSERT INTO tj.iqbuild_units(floor_id,unit_number,package_id) VALUES(f,'102',foreign_pkg);RAISE EXCEPTION 'Cross-project package accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM tj.iqbuild_package_items i JOIN tj.iqbuild_packages p ON p.id=i.package_id WHERE p.project_id=(r->>'project_id')::uuid AND i.unit_cost=0 AND i.width_inches=36 AND i.image_url='https://example.invalid/fixture.jpg' AND i.source_snapshot->>'image_url'='https://example.invalid/fixture.jpg' AND i.source_snapshot->'specifications'->>'capacity'='Recorded capacity' AND i.source_recorded_at<now()-interval '1 day') THEN RAISE EXCEPTION 'Source specs/zero price/date lost';END IF;
 IF NOT EXISTS(SELECT 1 FROM tj.iqbuild_units WHERE id=u AND organization_id=org AND notes='Saved note') OR NOT EXISTS(SELECT 1 FROM tj.iqbuild_projects WHERE id=project AND created_by=actor) THEN RAISE EXCEPTION 'Mapped creator/save failed';END IF;
 UPDATE tj.platform_user_context SET location_id=store WHERE user_id=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';INSERT INTO tj.iqbuild_packages(id,name) VALUES(store_pkg,'Store package');EXECUTE 'RESET ROLE';
 UPDATE tj.platform_user_context SET location_id=NULL WHERE user_id=actor;
 UPDATE tj.org_location_members SET is_active=false WHERE user_id=actor AND location_id=store;
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN UPDATE tj.iqbuild_units SET package_id=store_pkg WHERE id=u;RAISE EXCEPTION 'Revoked store package attached';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 UPDATE tj.organization_members SET status='suspended' WHERE organization_id=other AND user_id=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';SELECT count(*) INTO n FROM tj.iqbuild_projects WHERE id=foreign_project;IF n<>0 THEN RAISE EXCEPTION 'Foreign project visible';END IF;
 BEGIN INSERT INTO tj.iqbuild_buildings(project_id,name) VALUES(foreign_project,'Forbidden');RAISE EXCEPTION 'Foreign write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN UPDATE tj.iqbuild_signoffs SET notes='Rewrite history' WHERE project_id=project;RAISE EXCEPTION 'Signoff mutation accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 UPDATE tj.organization_members SET status='suspended' WHERE user_id=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';SELECT count(*) INTO n FROM tj.iqbuild_units WHERE id=u;IF n<>0 THEN RAISE EXCEPTION 'Suspended read accepted';END IF;EXECUTE 'RESET ROLE';
 IF has_table_privilege('anon','tj.iqbuild_projects','SELECT') THEN RAISE EXCEPTION 'Anonymous exposed';END IF;
END $$;
SELECT jsonb_build_object('passed',true,'fixtures_persisted',0,'checks',jsonb_build_array('mapped creator','project/building/floor/unit saves','packages and quoted source price','delivery and appliance','milestones','contacts and team','installation and parts','append-only signoff/activity','org derivation and spoof denial','foreign and suspended denial','CRM secondary link denial','SpecIQ product validation','source evidence immutable','unknown prices remain null','revoked standalone package denial')) verification;
ROLLBACK;
